import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';

test.describe(`team member: upload or create a document and tag it with keywords`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a member creates a document with tags (e.g., 'machine learning', 'Q3'), every other team member sees it in the document list within 5s with all tags displayed`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();

    try {
      await loginViaHash(pageA, 0);
      await loginViaHash(pageB, 1);

      // A creates a new document via the sidebar "+ New" button
      await pageA.getByRole('button', { name: '+ New' }).click();
      await pageA.getByPlaceholder('Document title…').fill('ML Initiative');
      await pageA.getByRole('button', { name: 'Create' }).click();

      // Wait for DocumentDetailView to appear (modal closed, doc selected)
      await expect(pageA.getByPlaceholder('add tag…')).toBeVisible({ timeout: 10_000 });

      // A adds tags in DocumentDetailView tag editor
      await pageA.getByPlaceholder('add tag…').fill('machine-learning');
      await pageA.getByRole('button', { name: '+' }).click();

      // Wait for first tag to persist before adding the second
      await expect(pageA.getByText('#machine-learning')).toBeVisible({ timeout: 10_000 });

      await pageA.getByPlaceholder('add tag…').fill('q3');
      await pageA.getByRole('button', { name: '+' }).click();

      // B sees the document in the sidebar within 5 s with all tags displayed
      await expect(pageB.getByText('ML Initiative')).toBeVisible({ timeout: 5_000 });
      await expect(pageB.getByText('#machine-learning')).toBeVisible({ timeout: 5_000 });
      await expect(pageB.getByText('#q3')).toBeVisible({ timeout: 5_000 });
    } finally {
      await clearAuth(pageA);
      await clearAuth(pageB);
      await ctxA.close();
      await ctxB.close();
    }
  });
});
